import base64, hashlib, json, struct, sys, zlib
from pathlib import Path

def verify(data, digest):
    if hashlib.sha256(data).hexdigest() != digest:
        raise ValueError("SHA-256 mismatch")
    return data

def unpack(blob):
    data = base64.b64decode(blob["data"], validate=True)
    if blob["encoding"] == "base64+zlib":
        data = zlib.decompress(data)
    elif blob["encoding"] != "base64":
        raise ValueError("Unknown encoding")
    if len(data) != blob["byte_length"]:
        raise ValueError("Byte length mismatch")
    return verify(data, blob["sha256"])

def chunk(kind, data):
    return struct.pack(">I", len(data)) + kind + data + struct.pack(">I", zlib.crc32(kind + data))

doc = json.loads(Path(sys.argv[1]).read_text())
output = Path(sys.argv[2])
mode = sys.argv[3] if len(sys.argv) > 3 else "original"
if mode == "original":
    output.write_bytes(unpack(doc["original_png"]))
elif mode == "raster":
    r = doc["raster"]
    w, h = r["width"], r["height"]
    result = bytearray(w * h * 4)
    for tile in r["tiles"]:
        data = unpack(tile)
        stride = tile["width"] * 4
        for line in range(tile["height"]):
            dst = ((tile["y"] + line) * w + tile["x"]) * 4
            result[dst:dst+stride] = data[line*stride:(line+1)*stride]
    verify(result, r["rgba_sha256"])
    rows = b"".join(b"\x00" + result[y*w*4:(y+1)*w*4] for y in range(h))
    header = struct.pack(">IIBBBBB", w, h, 8, 6, 0, 0, 0)
    output.write_bytes(bytes.fromhex("89504e470d0a1a0a") + chunk(b"IHDR", header) +
                       chunk(b"IDAT", zlib.compress(rows)) + chunk(b"IEND", b""))
else:
    raise ValueError("Use original or raster")
